// Edit these lists any time. Only matching emails are forwarded to Telegram.
const DOMAINS = ['upwork.com','mostaql.com','khamsat.com','nafezly.com','kafiil.com','fiverr.com','freelancer.com','zu.edu.eg'];
const WORDS = /(interview|offer|invoice|payment|deadline|exam|مقابلة|تسليم|امتحان|دفع|عرض عمل)/i;
const strip = (h) => String(h || '').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim();
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const from = typeof j.from === 'string' ? j.from : ((j.from && (j.from.text || (j.from.value && j.from.value[0] && j.from.value[0].address))) || '');
  const subject = String(j.subject || '');
  const low = from.toLowerCase();
  const important = DOMAINS.some(d => low.includes(d)) || WORDS.test(subject) || /^\s*\[job\]/i.test(subject);
  if (!important) continue;
  const body = (j.textPlain && String(j.textPlain).trim()) || strip(j.textHtml) || String(j.text || '');
  out.push({ json: { from: from.slice(0, 80), subject: subject.slice(0, 150), preview: body.slice(0, 220) } });
}
return out;

return $input.all().map((it, i) => {
  const m = $('Mail Filter').itemMatching(i).json;
  return { json: { chat: it.json.telegram_id, text: `📧 ${m.from}\n${m.subject}\n${m.preview}` } };
});
